SELECT CASE WHEN quantity >= 8 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, PERCENTILE_APPROX(unit_price, 0.9) AS unit_price_p90, ROUND(AVG(quantity), 2) AS avg_quantity, BIT_AND(quantity) AS quantity_bit_and, COUNT(*) AS cnt, CORR(unit_price, quantity) AS corr_unit_price_quantity, PERCENTILE_APPROX(unit_price, 0.5) AS unit_price_p50 FROM order_items GROUP BY CASE WHEN quantity >= 8 THEN 'HIGH' ELSE 'LOW' END;
